CREATE TABLE kits (
  id INTEGER PRIMARY KEY,
  price REAL CHECK (price > 0)
);

CREATE TABLE trips (
  id INTEGER PRIMARY KEY,
  start_date TEXT NOT NULL
);
INSERT INTO trips (start_date) VALUES ('2025-07-01');

CREATE TABLE pots (
  id INTEGER PRIMARY KEY,
  price REAL CHECK (price >= 0)
);
INSERT INTO pots (price) VALUES (-3);

CREATE TABLE packs (
  id INTEGER PRIMARY KEY,
  item TEXT NOT NULL,
  qty INTEGER NOT NULL DEFAULT 1
);
INSERT INTO packs (item) VALUES ('Headlamp');

CREATE TABLE gear (
  id INTEGER PRIMARY KEY,
  name TEXT
);
INSERT INTO gear (name) VALUES ('Lantern');

CREATE TABLE orders (
  id INTEGER PRIMARY KEY,
  gear_id INTEGER  -- plain INTEGER, no enforcement
);
INSERT INTO orders (gear_id) VALUES (99);
